import{_ as r,a as i,b as s}from"./chunks/PageInfo.vue_vue_type_script_setup_true_lang.BCVHfIj7.js";import{_ as o,c,I as a,a7 as l,o as p}from"./chunks/framework.DGCt2JJv.js";import"./chunks/dayjs.min.DZyl58SH.js";const z=JSON.parse('{"title":"react window","description":"","frontmatter":{},"headers":[],"relativePath":"react/React好用的插件/react-window.md","filePath":"react/React好用的插件/react-window.md","lastUpdated":1720539954000}'),d={name:"react/React好用的插件/react-window.md"},h=l(`<h1 id="react-window" tabindex="-1">react window <a class="header-anchor" href="#react-window" aria-label="Permalink to &quot;react window&quot;">​</a></h1><p>官网 <a href="https://github.com/bvaughn/react-window" target="_blank" rel="noreferrer">https://github.com/bvaughn/react-window</a> 控制宽高的包: react-virtualized-auto-sizer。</p><p>VariableSizeList 改变 item 高度</p><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes light-plus one-dark-pro vp-code" tabindex="0"><code><span class="line"><span>this.listRef = React.createRef()</span></span>
<span class="line"><span></span></span>
<span class="line"><span>&lt;VariableSizeList</span></span>
<span class="line"><span>  ref={this.listRef}</span></span>
<span class="line"><span>&gt;...&lt;/VariableSizeList</span></span>
<span class="line"><span></span></span>
<span class="line"><span>// item 高度变化时</span></span>
<span class="line"><span>this.listRef.current.resetAfterIndex(0, false)</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br><span class="line-number">8</span><br></div></div><h2 id="tanstack-react-virtual" tabindex="-1">@tanstack/react-virtual <a class="header-anchor" href="#tanstack-react-virtual" aria-label="Permalink to &quot;@tanstack/react-virtual&quot;">​</a></h2><p><a href="https://github.com/tanstack/virtual#readme" target="_blank" rel="noreferrer">https://github.com/tanstack/virtual#readme</a></p><h1 id="记录react性能优化之-虚拟滚动-技术——react-window" tabindex="-1">记录React性能优化之“虚拟滚动”技术——react-window <a class="header-anchor" href="#记录react性能优化之-虚拟滚动-技术——react-window" aria-label="Permalink to &quot;记录React性能优化之“虚拟滚动”技术——react-window&quot;">​</a></h1><h4 id="_1-虚拟化长列表" tabindex="-1">1. 虚拟化长列表 <a class="header-anchor" href="#_1-虚拟化长列表" aria-label="Permalink to &quot;1. 虚拟化长列表&quot;">​</a></h4><p>如果你的应用渲染了长列表（上百甚至上千的数据）时，React官网推荐我们使用“虚拟滚动”技术。这项技术会在有限的时间内仅渲染有限的内容，并奇迹般地降低重新渲染组件消耗的时间，以及创建 DOM 节点的数量。</p><p>React官网推荐我们使用<a href="https://links.jianshu.com/go?to=https%3A%2F%2Freact-window.now.sh%2F" target="_blank" rel="noreferrer">react-window</a>和 <a href="https://links.jianshu.com/go?to=https%3A%2F%2Fbvaughn.github.io%2Freact-virtualized%2F" target="_blank" rel="noreferrer">react-virtualized</a> 这2个热门的虚拟滚动库。它们提供了多种可复用的组件，用于展示列表、网格和表格数据。</p><h4 id="_2-react-window与react-virtualized有什么不同" tabindex="-1">2. react-window与react-virtualized有什么不同？ <a class="header-anchor" href="#_2-react-window与react-virtualized有什么不同" aria-label="Permalink to &quot;2. react-window与react-virtualized有什么不同？&quot;">​</a></h4><p>这2个库，出自于同一个作者。react-virtualized是作者对React和窗口概念都不熟悉时写的，加了一些API和添加了太多非必要的功能和组件，后来作者后悔了，但因为一旦向开源项目添加了一些东西，删除它对用户来说是非常痛苦的。所以作者完整重写了react-virtualized，并且更专注于使包装更小和更快。所以<a href="https://links.jianshu.com/go?to=https%3A%2F%2Fgithub.com%2Fbvaughn%2Freact-window" target="_blank" rel="noreferrer">react-window</a>是react-virtualized的轻量级替代品。</p><h4 id="_3-使用react-window网格的问题和解决方案" tabindex="-1">3.使用react-window网格的问题和解决方案 <a class="header-anchor" href="#_3-使用react-window网格的问题和解决方案" aria-label="Permalink to &quot;3.使用react-window网格的问题和解决方案&quot;">​</a></h4><p>我使用的是VariableSizeGrid（可变尺寸网格）。</p><p>问题1：使用itemData进行网格中数据的传递时，当columnCount（网格中的列数）*rowCount（网格中的行数）&gt;itemData.length，会出现网格滚动到最后一行时，最后一行没有被渲染。</p><p>方案1：给itemData 数组push（columnCount*rowCount- itemData.length）个对象｛true:true｝，然后在组件render时，进行判断return（<div></div>）</p><p>问题2：网格可以100％填充页面的宽度或高度吗？（这个问题作者有在npm上回答过）</p><p>方案2：网格宽高必须传入number类型，所以不能直接写’100%’，需要使用react-virtualized-auto-sizer包。</p><p>问题3：这个比较重要，没有提供可以传递方法的API。提供了可以在外层附加自定义属性或事件处理程序的API：outerElementType。但不能满足我想要点击按钮时才触发事件的需求。</p><h2 id="结合react-infinite-scroll-component实现滚动自动加载列表。" tabindex="-1">结合<a href="https://github.com/ankeetmaini/react-infinite-scroll-component" target="_blank" rel="noreferrer">react-infinite-scroll-component</a>实现滚动自动加载列表。 <a class="header-anchor" href="#结合react-infinite-scroll-component实现滚动自动加载列表。" aria-label="Permalink to &quot;结合[react-infinite-scroll-component](https://github.com/ankeetmaini/react-infinite-scroll-component)实现滚动自动加载列表。&quot;">​</a></h2><p><strong>height 高度</strong> 可选，仅当您想要具有固定高度的滚动内容时才提供</p><p><strong>scrollableTarget 可滚动的目标</strong> 可选，引用已向<code>InfiniteScroll</code>组件提供溢出滚动条的（父）DOM 元素。最好提供<code>id</code>DOM 节点。</p><p><a href="https://4x.ant.design/components/list-cn/#header" target="_blank" rel="noreferrer">https://4x.ant.design/components/list-cn/#header</a></p><h2 id="contributors" tabindex="-1">Contributors <a class="header-anchor" href="#contributors" aria-label="Permalink to &quot;Contributors&quot;">​</a></h2>`,24);function u(m,b,w,_,f,g){const e=r,t=i,n=s;return p(),c("div",null,[h,a(e,{readTime:"2",words:"717"}),a(t),a(n)])}const q=o(d,[["render",u]]);export{z as __pageData,q as default};
